import test from "node:test";
import assert from "node:assert/strict";
import {
	closeStore,
	confirmProposed,
	exportBundle,
	importBundle,
	openStore,
	overview,
	pendingFacts,
	propose,
	rejectProposed,
	remember,
	search,
} from "../lib/store.js";

/** @returns {{store: any}} fresh in-memory store. */
function fresh() {
	return { store: openStore(":memory:") };
}

test("a proposed fact waits outside live/search until confirmed", () => {
	const { store } = fresh();
	try {
		const outcome = propose(store, { subject: "self", predicate: "allergy", object: "花生" });
		assert.equal(outcome.fact.status, "proposed");
		assert.equal(overview(store).counts.facts, 0);
		assert.equal(overview(store).counts.pending, 1);
		assert.equal(pendingFacts(store).length, 1);
		assert.equal(search(store, { predicate: "allergy" }).length, 0);
		assert.equal(search(store, { predicate: "allergy", history: true }).length, 1);

		const confirmed = confirmProposed(store, outcome.fact.id);
		assert.equal(confirmed.fact.status, "asserted");
		assert.equal(overview(store).counts.facts, 1);
		assert.equal(overview(store).counts.pending, 0);
		assert.equal(search(store, { predicate: "allergy" })[0].object, "花生");
	} finally {
		closeStore(store);
	}
});

test("confirming a newer candidate supersedes the live single value", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "city", object: "上海", observedAt: "2020-01-01T00:00:00.000Z", validFrom: "2020-01-01T00:00:00.000Z" });
		const candidate = propose(store, {
			subject: "self", predicate: "city", object: "北京",
			observedAt: "2024-01-01T00:00:00.000Z", validFrom: "2024-01-01T00:00:00.000Z",
		});
		const confirmed = confirmProposed(store, candidate.fact.id);
		assert.deepEqual(confirmed.superseded.length, 1);
		assert.equal(search(store, { predicate: "city" })[0].object, "北京");
		assert.equal(search(store, { predicate: "city", history: true }).length, 2);
	} finally {
		closeStore(store);
	}
});

test("confirming an older candidate keeps it as history", () => {
	const { store } = fresh();
	try {
		remember(store, { subject: "self", predicate: "city", object: "北京", observedAt: "2024-01-01T00:00:00.000Z", validFrom: "2024-01-01T00:00:00.000Z" });
		const candidate = propose(store, {
			subject: "self", predicate: "city", object: "上海",
			observedAt: "2020-01-01T00:00:00.000Z", validFrom: "2020-01-01T00:00:00.000Z",
		});
		const confirmed = confirmProposed(store, candidate.fact.id);
		assert.equal(confirmed.historical, true);
		assert.equal(search(store, { predicate: "city" })[0].object, "北京");
		assert.equal(search(store, { predicate: "city", history: true }).length, 2);
		assert.equal(overview(store).counts.pending, 0);
	} finally {
		closeStore(store);
	}
});

test("reject removes the candidate and duplicate proposals are suppressed", () => {
	const { store } = fresh();
	try {
		const first = propose(store, { subject: "self", predicate: "likes", object: "徒步" });
		const second = propose(store, { subject: "self", predicate: "likes", object: "徒步" });
		assert.equal(second.duplicate, true);
		assert.equal(pendingFacts(store).length, 1);
		rejectProposed(store, first.fact.id);
		assert.equal(pendingFacts(store).length, 0);
		assert.equal(overview(store).counts.pending, 0);
	} finally {
		closeStore(store);
	}
});

test("an explicit assertion clears a pending duplicate", () => {
	const { store } = fresh();
	try {
		propose(store, { subject: "self", predicate: "name", object: "林舟" });
		remember(store, { subject: "self", predicate: "name", object: "林舟", sourceKind: "user" });
		assert.equal(pendingFacts(store).length, 0);
		assert.equal(search(store, { predicate: "name" }).length, 1);
	} finally {
		closeStore(store);
	}
});

test("two stores exchanging bundles report the conflict and keep the newer value", () => {
	const a = openStore(":memory:");
	const b = openStore(":memory:");
	try {
		remember(a, { subject: "self", predicate: "city", object: "上海", observedAt: "2020-01-01T00:00:00.000Z", validFrom: "2020-01-01T00:00:00.000Z" });
		remember(b, { subject: "self", predicate: "city", object: "北京", observedAt: "2024-01-01T00:00:00.000Z", validFrom: "2024-01-01T00:00:00.000Z" });

		const first = importBundle(b, exportBundle(a), { sourceRef: "bundle:from-a.json" });
		assert.equal(first.conflicts.length, 1);
		assert.equal(first.conflicts[0].local, "北京");
		assert.equal(first.conflicts[0].incoming, "上海");
		assert.equal(first.conflicts[0].kept, "北京");
		assert.equal(search(b, { predicate: "city" })[0].object, "北京");

		remember(b, { subject: "self", predicate: "city", object: "深圳", observedAt: "2026-01-01T00:00:00.000Z", validFrom: "2026-01-01T00:00:00.000Z" });
		const second = importBundle(a, exportBundle(b), { sourceRef: "bundle:from-b.json" });
		assert.equal(second.conflicts.length, 1);
		assert.equal(second.conflicts[0].local, "上海");
		assert.equal(second.conflicts[0].incoming, "深圳");
		assert.equal(second.conflicts[0].kept, "深圳");
		assert.equal(search(a, { predicate: "city" })[0].object, "深圳");
	} finally {
		closeStore(a);
		closeStore(b);
	}
});
